function decode(b64) {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

// A fresh 64K image for each engine, since the engine writes to it.
export function gameImage() {
  const m = new Uint8Array(0x10000);
  m.set(decode(RAM), 0x4000);
  return m;
}
